13	/**
14	 * Downloadable plain-text receipt for a completed booking. Returns an
15	 * attachment; the booking must belong to the caller (RLS-enforced read).
16	 */
17	export async function GET(
18	  _req: NextRequest,
19	  ctx: { params: Promise<{ bookingId: string }> },
20	) {
21	  const user = await getUser();
22	  if (!user) {
23	    return new Response(t("receipt.notFound"), { status: 401 });
24	  }
25	  const { bookingId } = await ctx.params;
26	  const [booking, session] = await Promise.all([
27	    getBooking(bookingId),
28	    getSessionByBooking(bookingId),
29	  ]);
30	  if (!booking || booking.customer_id !== user.id || !session) {
31	    return new Response(t("receipt.notFound"), { status: 404 });
32	  }
33	
34	  const provider = await getApprovedProvider(booking.provider_id);
35	  const supabase = await createClient();
36	  const { data: payment } = await supabase
37	    .from("payments")
38	    .select("payment_ref, status")
39	    .eq("booking_id", bookingId)
40	    .maybeSingle();
41	
42	  const lines = [
43	    t("receipt.heading"),
44	    "",
45	    `${t("receipt.booking")}: ${booking.id}`,
46	    `${t("receipt.listener")}: ${provider?.display_name ?? "—"}`,
47	    `${t("receipt.date")}: ${session.ended_at ?? "—"}`,
48	    `${t("receipt.duration")}: ${durationLabel(session.elapsed_seconds)}`,
49	    `${t("receipt.block")}: ${t("receipt.minutes", { minutes: session.block_minutes })}`,
50	    session.overage_minutes > 0
51	      ? `${t("receipt.overage")}: ${t("receipt.minutes", { minutes: session.overage_minutes })}`
52	      : null,
53	    `${t("receipt.total")}: ${formatCents(session.total_price_cents)}`,
54	    `${t("receipt.payment")}: ${payment?.payment_ref ?? "—"} (${payment?.status ?? "—"})`,
55	    "",
56	    t("receipt.footer"),
57	    "",
58	  ]
59	    .filter((l) => l !== null)
60	    .join("\n");
61	
62	  return new Response(lines, {
63	    status: 200,
64	    headers: {
65	      "Content-Type": "text/plain; charset=utf-8",
66	      "Content-Disposition": `attachment; filename="heard-receipt-${booking.id.slice(0, 8)}.txt"`,
67	    },
68	  });
69	}
